if(!isset($u,$tab)||!function_exists('ad_role')){http_response_code(404);exit;}
function ah(string $name,$value): string{return '<input type="hidden" name="'.e($name).'" value="'.e($value).'">';}
function af(string $name,string $label,string $type='text',$value='',string $attrs=''): string{return '<label><span>'.e($label).'</span><input type="'.e($type).'" name="'.e($name).'" value="'.e($value).'" '.$attrs.'></label>';}
function at(string $name,string $label,$value='',int $max=3000): string{return '<label><span>'.e($label).'</span><textarea name="'.e($name).'" maxlength="'.$max.'" rows="3">'.e($value).'</textarea></label>';}
function ase(string $name,string $label,array $items,$value=''): string{$s='<label><span>'.e($label).'</span><select name="'.e($name).'">';foreach($items as $k=>$v)$s.='<option value="'.e($k).'"'.((string)$k===(string)$value?' selected':'').'>'.e($v).'</option>';return $s.'</select></label>';}
function ao(array $values): array{return array_combine($values,array_map(fn($v)=>ucwords(str_replace('_',' ',$v)),$values));}
function apass(bool $required=true): string{return af('current_password','Current Head password','password','',($required?'required ':'').'autocomplete="current-password"');}
function av(array $r): string{return ah('id',$r['id']).ah('version',$r['version']);}
function aform(string $action,string $fields,string $button='Save'): string{return '<form class="ad-form" method="post" action="'.e(url('guidance/staff-action.php')).'">'.csrf_field().ah('action',$action).ah('request_token',bin2hex(random_bytes(16))).$fields.'<button class="btn btn-primary" type="submit">'.e($button).'</button></form>';}
function acard(string $title,string $body): string{return '<section class="ad-card"><h2>'.e($title).'</h2>'.$body.'</section>';}
function adetail(string $title,string $body): string{return '<details><summary>'.e($title).'</summary>'.$body.'</details>';}
function anote(string $s): string{return '<p class="ad-note">'.e($s).'</p>';}
function abody(string $s): string{return '<p class="ad-text">'.nl2br(e($s)).'</p>';}
function alink(string $tab,string $label,int $ticket=0): string{return '<a class="btn" href="'.e(url('guidance/staff.php?'.http_build_query(['tab'=>$tab,'ticket'=>$ticket]))).'">'.e($label).'</a>';}
function ar(string $key,string $sql,array $args=[]): array {
    $page=gi($_GET,'p_'.$key,1,10000,1);$sql=preg_replace('/LIMIT 51\s*$/','LIMIT 51 OFFSET '.(($page-1)*50),$sql);
    return ['_ad_key'=>$key,'_ad_page'=>$page,'_ad_rows'=>gall($sql,$args)];
}
function alist(array $rows,callable $render): string {
    $key=$rows['_ad_key']??null;$page=$rows['_ad_page']??1;if($key)$rows=$rows['_ad_rows'];
    $s=$rows?'':anote('No matching records on this page.');
    foreach($key?array_slice($rows,0,50):$rows as $r)$s.='<article class="ad-record">'.$render($r).'</article>';
    if($key&&($page>1||count($rows)>50)){$s.='<nav class="ad-pager" aria-label="Record pages"><span>Page '.e($page).' · up to 50 records</span>';foreach(['Previous'=>-1,'Next'=>1] as $label=>$step){if(($step<0&&$page<=1)||($step>0&&count($rows)<=50))continue;$q=$_GET;$q['p_'.$key]=$page+$step;$s.='<a class="btn" href="'.e(url('guidance/staff.php?'.http_build_query($q))).'">'.e($label).'</a>';}$s.='</nav>';}
    return $s;
}
