    echo '<div class="ad-grid">'.acard('Recurring staff availability',anote('Rules apply to new staff bookings/rescheduling and confirmation through the existing appointment screen. Existing confirmed appointments are not silently cancelled. Retiring a rule does not cancel them.').aform('rule.create',ase('counselor_id','Counselor',$clinicians,$u['id']).ase('weekday','Weekday',[1=>'Monday',2=>'Tuesday',3=>'Wednesday',4=>'Thursday',5=>'Friday',6=>'Saturday',7=>'Sunday'],1).af('starts_time','Start','time','09:00','required').af('ends_time','End','time','16:00','required').af('slot_minutes','Appointment length (minutes)','number',30,'min="15" max="120" required').af('buffer_minutes','Buffer between appointments (minutes)','number',10,'min="0" max="60" required').af('effective_from','Effective from','date',date('Y-m-d'),'required').af('effective_to','Effective through','date',date('Y-m-d',strtotime('+90 days')),'required'),'Publish availability'));
    echo acard('Block unavailable time',aform('block.create',ase('counselor_id','Counselor',$clinicians,$u['id']).af('starts_at','Blocked from','datetime-local',$tomorrow.'T09:00','required').af('ends_at','Blocked until','datetime-local',$tomorrow.'T10:00','required').af('reason','Administrative reason — no student details','text','','required maxlength="160"'),'Block time')).'</div>';
    echo acard('Published availability',alist(ar('records13','SELECT * FROM gd_adv_rules WHERE '.$where.' AND active=1 ORDER BY counselor_id,weekday,starts_time,id LIMIT 51',$args),fn($r)=>'<h3>'.e($clinicians[$r['counselor_id']]??'Counselor').'</h3><p>Weekday '.e($r['weekday']).' · '.e($r['starts_time'].'–'.$r['ends_time']).' · '.e($r['slot_minutes']).' min + '.e($r['buffer_minutes']).' min buffer</p><p>'.e($r['effective_from'].' through '.$r['effective_to']).'</p>'.aform('rule.retire',av($r),'Retire rule')));
    echo acard('Blocked time',alist(ar('records14','SELECT * FROM gd_adv_blocks WHERE '.$where.' AND active=1 AND ends_at>NOW() ORDER BY starts_at,id LIMIT 51',$args),fn($r)=>'<p>'.e($clinicians[$r['counselor_id']]??'Counselor').' · '.e($r['starts_at'].'–'.$r['ends_at']).'</p>'.abody($r['reason']).aform('block.retire',av($r),'Release block')));
    if($selected){
        $wait=gall("SELECT * FROM gd_adv_waitlist WHERE ticket_id=? AND status IN ('waiting','offered') ORDER BY created_at",[$ticket]);
        echo '<div class="ad-grid">'.acard('Appointment waitlist',anote('Separate from activity waitlists. Urgency is staff-entered, not a diagnostic score. An offer is not a confirmed appointment.').aform('waitlist.create',$caseHidden.ase('counselor_id','Counselor',$clinicians,$selected['assigned_to']).af('earliest_on','Earliest date','date',$tomorrow,'required').af('latest_on','Latest date','date',$nextMonth,'required').ase('priority','Staff scheduling priority',ao(['routine','soon','urgent'])),'Join appointment waitlist'));
        echo acard('Book a confirmed appointment',anote('Use a published slot; start must align with the rule’s appointment + buffer grid. The existing student portal will show the confirmed appointment; no new student interface or notification is added.').aform('appointment.save',$caseHidden.ase('counselor_id','Counselor',$clinicians,$selected['assigned_to']).af('starts_at','Start','datetime-local',$tomorrow.'T09:00','required').af('ends_at','End','datetime-local',$tomorrow.'T09:30','required').at('concern','Appointment concern / purpose (visible in existing appointment record)','',4000),'Check availability and book')).'</div>';
        echo acard('Waiting appointment requests',alist($wait,function($r)use($caseHidden,$clinicians,$tomorrow){return '<h3>'.e($r['priority'].' · '.$r['status']).'</h3><p>'.e($r['earliest_on'].' to '.$r['latest_on']).'</p>'.aform('waitlist.update',av($r).ase('status','Next state',ao(['offered','withdrawn'])),'Record offer / withdrawal').adetail('Book this waitlist request',aform('appointment.save',ah('waitlist_id',$r['id']).ah('version',$r['version']).$caseHidden.ah('counselor_id',$r['counselor_id']).af('starts_at','Start','datetime-local',$tomorrow.'T09:00','required').af('ends_at','End','datetime-local',$tomorrow.'T09:30','required').at('concern','Appointment purpose (existing student-visible record)' ,'',4000),'Book atomically and close waitlist'));}));
    }
