    $args=$head?[]:[$u['id']];$where=$head?'1=1':'a.counselor_id=?';if($selected){$where.=' AND a.user_id=?';$args[]=$selected['user_id'];}
    $appointments=ar('records15','SELECT a.*,u.full_name AS requester,c.full_name AS counselor,m.attendance_state,m.reason AS outcome_note FROM gd_appointments a LEFT JOIN gd_adv_appointments m ON m.appointment_id=a.id JOIN users u ON u.id=a.user_id JOIN users c ON c.id=a.counselor_id WHERE '.$where.' ORDER BY a.starts_at DESC,a.id DESC LIMIT 51',$args);
    echo acard('Authorized appointments',alist($appointments,function($r)use($selected,$caseHidden,$clinicians){$native=array_intersect_key($r,array_flip(['id','user_id','counselor_id','starts_at','ends_at','concern','status','updated_at']));$s='<h3>'.e($r['requester'].' · '.$r['status']).'</h3><p>'.e($r['starts_at'].'–'.$r['ends_at'].' · '.$r['counselor']).'</p>'.($r['attendance_state']&&$r['attendance_state']!=='scheduled'?anote('Staff-recorded outcome: '.$r['attendance_state']).abody($r['outcome_note']):'');$stamp=ad_appointment_stamp($native);
        if($selected&&in_array($r['status'],['requested','confirmed'],true))$s.=adetail('Reschedule / confirm in published availability',aform('appointment.save',$caseHidden.ah('id',$r['id']).ah('expected_stamp',$stamp).ase('counselor_id','Counselor',$clinicians,$r['counselor_id']).af('starts_at','New start','datetime-local',date('Y-m-d\TH:i',strtotime($r['starts_at'])),'required').af('ends_at','New end','datetime-local',date('Y-m-d\TH:i',strtotime($r['ends_at'])),'required').at('concern','Appointment purpose (existing student-visible record)' ,$r['concern'],4000),'Validate and reschedule'));
        if($r['status']==='confirmed'&&$r['ends_at']<=date('Y-m-d H:i:s'))$s.=aform('appointment.attendance',ah('id',$r['id']).ah('expected_stamp',$stamp).ase('attendance_state','Verified outcome',ao(['attended','no_show'])).at('reason','Staff verification / contact note','',1000),'Record attendance outcome');return $s;}));
}
